  if (mode == "ring") {
    return LowerTensorRingAllReduceRule(call, args, b);
  }

  auto signal_type = As<DistributedTensorType>(signal->GetType());
  ValidateMeshSignalShape(signal_type, "pld.tensor.allreduce", span);

